#include <iostream>
int main() {
    int a[] = {1, 2, 3, 4, 5}, k = 3;
    int s = 0;
    for (int i = 0; i < k; i++) s += a[i];
    int best = s;
    for (int i = k; i < 5; i++) {
        s += a[i] - a[i - k];
        if (s > best) best = s;
    }
    std::cout << best;
}

