#include <algorithm>
#include <iostream>
int main() {
    int a[] = {2, 0, 2, 1, 0}, n = 5;
    int lo = 0, mid = 0, hi = n - 1;
    while (mid <= hi) {
        if (a[mid] == 0) std::swap(a[lo++], a[mid++]);
        else if (a[mid] == 1) mid++;
        else std::swap(a[mid], a[hi--]);
    }
    std::cout << a[0] << a[1] << a[2] << a[3] << a[4];
}

#include <iostream>
int main() {
    int a[] = {1, -2, 3, -1, 2};
    int best = a[0], cur = a[0];
    for (int i = 1; i < 5; i++) {
        cur = (cur > 0 ? cur + a[i] : a[i]);
        if (cur > best) best = cur;
    }
    std::cout << best;
}
